package com.realstant.nativegame; import android.content.*; public final class GameSession { public final GameState state=new GameState(); public final PhysicsState physics=new PhysicsState(); public final InputState input=new InputState(); public final PhysicsEngine engine=new PhysicsEngine(); public final WeatherSystem weather=new WeatherSystem(); public final CheckpointSystem checkpoints=new CheckpointSystem(); public final RaceTimer timer=new RaceTimer(); private final VehicleSpec vehicle; public GameSession(Context c){vehicle=VehicleCatalog.all().get(0);new SaveManager(c).load(state);checkpoints.build();} public void update(float dt){engine.update(physics,input,dt,vehicle);weather.update(dt);checkpoints.update(physics.x,physics.z);} }
